To utilize Go programming language to perform an extensive evaluation of the various effects of climate change on different ecosystems and societies, you can start by accessing climate data from reliable sources such as the National Oceanic and Atmospheric Administration (NOAA). The NOAA Climate Data Online API provides a wealth of climate data that you can use to analyze the effects of climate change on different ecosystems and societies.
To extract and analyze climate data from a specific location using the NOAA Climate Data Online API, you can use the following Go code snippet:
```
package main
import (
    "encoding/json"
    "fmt"
    "io/ioutil"
    "net/http"
)
func main() {
    // Set the location and date range for the climate data
    location := "Baltimore,MD"
    startDate := "2020-01-01"
    endDate := "2020-12-31"
    // Build the API request URL
    apiUrl := fmt.Sprintf("https://www.ncdc.noaa.gov/cdo-web/api/v2/data?datasetid=GHCND&locationid=FIPS:%s&startdate=%s&enddate=%s", location, startDate, endDate)
    // Set the API token
    apiToken := "INSERT_YOUR_API_TOKEN_HERE"
    // Build the API request
    req, err := http.NewRequest("GET", apiUrl, nil)
    if err != nil {
        fmt.Println(err)
        return
    }
    req.Header.Set("token", apiToken)
    // Send the API request and get the response
    client := &http.Client{}
    resp, err := client.Do(req)
    if err != nil {
        fmt.Println(err)
        return
    }
    defer resp.Body.Close()
    // Read the response body
    body, err := ioutil.ReadAll(resp.Body)
    if err != nil {
        fmt.Println(err)
        return
    }
    // Unmarshal the response body into a JSON object
    var data map[string]interface{}
    err = json.Unmarshal(body, &data)
    if err != nil {
        fmt.Println(err)
        return
    }
    // Print the climate data
    fmt.Println(data)
}
```
