How can we use Go to create a RESTful API that retrieves and stores data for a list of quotes and their authors? 
[Go code]:
package main
import (
	"encoding/xml"
	"log"
	"net/http"
	"strings"
	"github.com/gorilla/mux"
)
type Quote struct {
	Text   string `xml:"text"`
	Author string `xml:"author"`
}
type QuoteList struct {
	XMLName xml.Name `xml:"quoteList"`
	Quotes  []Quote  `xml:"quote"`
}
var quotes QuoteList
func main() {
	// Load quotes from XML file
	xmlData := `<quoteList>
	<quote>
		<text>The only way to do great work is to love what you do.</text>
		<author>Steve Jobs</author>
	</quote>
	<quote>
		<text>You don't have to be great to start, but you have to start to be great.</text>
		<author>Zig Ziglar</author>
	</quote>
	<quote>
		<text>Success is not final, failure is not fatal: it is the courage to continue that counts.</text>
		<author>Winston Churchill</author>
	</quote>
	<quote>
		<text>If you want to live a happy life, tie it to a goal, not to people or things.</text>
		<author>Albert Einstein</author>
	</quote>
</quoteList>`
	xml.Unmarshal([]byte(xmlData), &quotes)
	// Create router
	r := mux.NewRouter()
	// Retrieve all quotes
	r.HandleFunc("/quotes", getAllQuotes).Methods("GET")
	// Retrieve quote by author
	r.HandleFunc("/quotes/{author}", getQuoteByAuthor).Methods("GET")
	// Add new quote
	r.HandleFunc("/quotes", addQuote).Methods("POST")
	// Start server
	log.Fatal(http.ListenAndServe(":8080", r))
}
func getAllQuotes(w http.ResponseWriter, r *http.Request) {
	xmlBytes, err := xml.MarshalIndent(quotes, "", "  ")
	if err != nil {
		log.Fatal(err)
	}
	w.Header().Set("Content-Type", "application/xml")
	w.Write(xmlBytes)
}
func getQuoteByAuthor(w http.ResponseWriter, r *http.Request) {
	vars := mux.Vars(r)
	author := vars["author"]
	for _, quote := range quotes.Quotes {
		if strings.ToLower(quote.Author) == strings.ToLower(author) {
			xmlBytes, err := xml.MarshalIndent(quote, "", "  ")
			if err != nil {
				log.Fatal(err)
			}
			w.Header().Set("Content-Type", "application/xml")
			w.Write(xmlBytes)
			return
		}
	}
	http.NotFound(w, r)
}
func addQuote(w http.ResponseWriter, r *http.Request) {
	var quote Quote
	err := xml.NewDecoder(r.Body).Decode(&quote)
	if err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	quotes.Quotes = append(quotes.Quotes, quote)
	w.WriteHeader(http.StatusCreated)
}

