import java.util.*;
public class DinnerParty {
    public static void main(String[] args) {
        // Prompt guests for their preferences
        Map<String, List<String>> guestPreferences = new HashMap<>();
        Scanner scanner = new Scanner(System.in);
        List<String> guests = Arrays.asList("John", "Sarah", "Tom");
