// Shuffle the list of numbers
shuffle($numbers);
// Define a helper function to check if a number can be placed at a given position
function canPlaceNumber($number, $x, $y, $grid) {
    // Check if the number is already present in the same row or column
    for ($i = 0; $i < 3; $i++) {
        if ($grid[$x][$i] == $number || $grid[$i][$y] == $number) {
            return false;
        }
    }
    // Check if the number is adjacent to another number
    if ($x > 0 && abs($grid[$x - 1][$y] - $number) <= 1) {
        return false;
    }
    if ($y > 0 && abs($grid[$x][$y - 1] - $number) <= 1) {
        return false;
    }
    return true;
}
// Define a recursive function to fill the grid
function fillGrid(&$grid, &$numbers, $x, $y, $targetSum) {
    // If we have filled all cells, check if the grid is valid
    if ($x == 3 && $y == 0) {
        // Check rows
        for ($i = 0; $i < 3; $i++) {
            if (array_sum($grid[$i]) != $targetSum) {
                return false;
            }
        }
        // Check columns
        for ($j = 0; $j < 3; $j++) {
            $sum = 0;
            for ($i = 0; $i < 3; $i++) {
                $sum += $grid[$i][$j];
            }
            if ($sum != $targetSum) {
                return false;
            }
        }
        // Check diagonals
        if ($grid[0][0] + $grid[1][1] + $grid[2][2] != $targetSum) {
            return false;
        }
        if ($grid[0][2] + $grid[1][1] + $grid[2][0] != $targetSum) {
            return false;
        }
        // If the grid is valid, we're done
        return true;
    }
    // Try to place each available number at the current position
    foreach ($numbers as $number) {
        if (canPlaceNumber($number, $x, $y, $grid)) {
            // Place the number
            $grid[$x][$y] = $number;
            // Remove the number from the list of available numbers
            $index = array_search($number, $numbers);
            array_splice($numbers, $index, 1);
            // Try to fill the next cell
            $nextX = $x + 1;
            $nextY = $y;
            if ($nextX == 3) {
                $nextX = 0;
                $nextY = $y + 1;
            }
            if (fillGrid($grid, $numbers, $nextX, $nextY, $targetSum)) {
                return true;
            }
            // If we couldn't fill the next cell, backtrack
            $grid[$x][$y] = 0;
            array_splice($numbers, $index, 0, $number);
        }
    }
    // If no number could be placed at the current position, backtrack
    return false;
}
// Fill the grid
fillGrid($grid, $numbers, 0, 0, $targetSum);
// Print the grid
for ($i = 0; $i < 3; $i++) {
    for ($j = 0; $j < 3; $j++) {
