To handle grammatical errors and rearrange the sentence accordingly, you can use a dependency parser to parse the sentence and identify the relationships between the words. Here is an example using Stanford.NLP:
```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using edu.stanford.nlp.ling;
using edu.stanford.nlp.pipeline;
using edu.stanford.nlp.util;
namespace POS_Tagger
{
    class Program
    {
        static void Main(string[] args)
        {
            // Create a new pipeline with default properties
            var pipeline = new StanfordCoreNLP(Properties.CoreNLPDefaultConfig);
            // Get input sentence from user
            Console.WriteLine("Enter a sentence:");
            string input = Console.ReadLine();
            // Annotate the input sentence
            var annotation = new Annotation(input);
            pipeline.annotate(annotation);
            // Get the list of annotated words and dependencies
            var words = annotation.get(typeof(CoreAnnotations.TokensAnnotation))
                .asInstanceOf<java.util.ArrayList<CoreLabel>>()
                .ToList();
            var dependencies = annotation.get(typeof(CoreAnnotations.CollapsedCCProcessedDependenciesAnnotation))
                .asInstanceOf<java.util.ArrayList<TypedDependency>>()
                .ToList();
            // Rearrange the words according to their dependencies
            var sortedWords = new List<CoreLabel>();
            foreach (var dependency in dependencies)
            {
                if (dependency.reln().getShortName() == "root")
                {
                    sortedWords.Add(words[dependency.dep().index() - 1]);
                    break;
                }
            }
            while (sortedWords.Count < words.Count)
            {
                foreach (var dependency in dependencies)
                {
                    if (sortedWords.Contains(dependency.gov()) && !sortedWords.Contains(dependency.dep()))
                    {
                        sortedWords.Add(dependency.dep());
                    }
                }
            }
            // Create a table to display the parts of speech for each word
            Console.WriteLine("| Word | Part of Speech |");
            Console.WriteLine("|------|----------------|");
            // Loop through the sorted words and display their parts of speech
            foreach (var word in sortedWords)
            {
                string pos = word.get(typeof(CoreAnnotations.PartOfSpeechAnnotation)).ToString();
                Console.WriteLine($"| {word.word()} | {pos} |");
            }
            Console.ReadLine();
        }
    }
}
```
This code uses Stanford.NLP to annotate the input sentence, extract the dependencies between the words, and rearrange the words according to their dependencies. It then displays the results in a table.

