    question: "Who is the only player to have won the NBA MVP award, NBA Finals MVP award, and Olympic gold medal in the same year?",
    options: ["Michael Jordan", "LeBron James", "Kobe Bryant", "Magic Johnson"],
    answer: "Michael Jordan"
  },
  {
    question: "Who is the all-time leading wicket-taker in Test cricket?",
    options: ["Shane Warne", "Muttiah Muralitharan", "Anil Kumble", "Glenn McGrath"],
    answer: "Muttiah Muralitharan"
  },
  {
    question: "Who is the only player to have won the FIFA World Cup, UEFA Champions League, and domestic league title in four different countries?",
    options: ["Cristiano Ronaldo", "Lionel Messi", "Zlatan Ibrahimovic", "Andres Iniesta"],
    answer: "Zlatan Ibrahimovic"
  }
];
// Variables
let currentQuestion = 0;
let score = 0;
let timer;
// Function to display question and options
function displayQuestion() {
  const questionElement = document.getElementById("question");
  const optionsElement = document.getElementById("options");
  const currentQuestionObj = questions[currentQuestion];

  questionElement.innerHTML = currentQuestionObj.question;

  let optionsHtml = "";
  for (let i = 0; i < currentQuestionObj.options.length; i++) {
    optionsHtml += `<button onclick="checkAnswer('${currentQuestionObj.options[i]}')">${currentQuestionObj.options[i]}</button>`;
  }
  optionsElement.innerHTML = optionsHtml;
}
// Function to check answer
function checkAnswer(answer) {
  clearInterval(timer);

  const currentQuestionObj = questions[currentQuestion];
  if (answer === currentQuestionObj.answer) {
    score++;
  }

  // Display correct answer and score
  const answerElement = document.getElementById("answer");
  answerElement.innerHTML = `Correct answer: ${currentQuestionObj.answer}`;
  const scoreElement = document.getElementById("score");
  scoreElement.innerHTML = `Score: ${score}`;

  // Move to next question or end game
  currentQuestion++;
  if (currentQuestion === questions.length) {
    endGame();
  } else {
    setTimeout(displayQuestion, 2000);
  }
}
// Function to start game
function startGame() {
  currentQuestion = 0;
  score = 0;
  timer = setInterval(endGame, 10000);

  // Hide start button and show game elements
  const startButton = document.getElementById("start-button");
  startButton.style.display = "none";
  const gameElements = document.getElementsByClassName("game-element");
  for (let i = 0; i < gameElements.length; i++) {
    gameElements[i].style.display = "block";
  }

  displayQuestion();
}
// Function to end game
function endGame() {
  clearInterval(timer);

  // Hide game elements and show high scores
  const gameElements = document.getElementsByClassName("game-element");
  for (let i = 0; i < gameElements.length; i++) {
    gameElements[i].style.display = "none";
  }
  const highScoresElement = document.getElementById("high-scores");
  highScoresElement.style.display = "block";

  // Add score to high scores list
  const highScoresList = JSON.parse(localStorage.getItem("highScores")) || [];
  highScoresList.push(score);
  highScoresList.sort((a, b) => b - a);
  highScoresList.splice(5);
  localStorage.setItem("highScores", JSON.stringify(highScoresList));

  // Display high scores list
  const highScoresListElement = document.getElementById("high-scores-list");
  let highScoresListHtml = "";
  for (let i = 0; i < highScoresList.length; i++) {
    highScoresListHtml += `<li>${highScoresList[i]}</li>`;
  }
  highScoresListElement.innerHTML = highScoresListHtml;
}
// Function to reset game
function resetGame() {
  localStorage.removeItem("highScores");
  location.reload();
}
// Event listeners
const startButton = document.getElementById("start-button");
startButton.addEventListener("click", startGame);
const resetButton = document.getElementById("reset-button");
resetButton.addEventListener("click", resetGame);
```
To use this code, you'll need to create an HTML file with the following elements:
```
<h1>Famous Athletes Trivia</h1>
<button id="start-button">Start Game</button>
<div id="question"></div>
<div id="options"></div>
<div id="answer"></div>
<div id="score"></div>
<div class="game-element" style="display: none;">
  <h2>Time Remaining: <span id="timer">10</span> seconds</h2>
</div>
<div class="game-element" style="display: none;">
  <h2>High Scores</h2>
  <ol id="high-scores-list"></ol>
  <button id="reset-button">Reset Game</button>
</div>
<script src="script.js"></script>
```
This code creates a trivia game with 10 questions about famous athletes from different sports. Each question has a timer of 10 seconds and the game keeps track of the player's score. After each question, the player can see their score and the correct answer. At the end of the game, the top 5 high scores are displayed.
To play the game, simply open the HTML file in your web browser and click the "Start Game" button. Good luck!

