Here's a Java program that creates two string objects and outputs their length and concatenation in reverse order using a SQL query:
```
import java.sql.*;
public class StringObjects {
  public static void main(String[] args) {
    String sentence = "The quick brown fox jumps over the lazy dog";
    String mixedCase = "AbCdEfGhIjK";
    try {
      // Create a connection to a SQL database
      Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydatabase", "username", "password");
      // Get the length of the sentence string and output it
      int sentenceLength = sentence.length();
      System.out.println("Length of sentence string: " + sentenceLength);
      // Get the length of the mixedCase string and output it
      int mixedCaseLength = mixedCase.length();
      System.out.println("Length of mixedCase string: " + mixedCaseLength);
      // Concatenate the two strings in reverse order and output the result using a SQL query
      String reversedConcat = new StringBuilder(sentence).reverse().toString() + new StringBuilder(mixedCase).reverse().toString();
      Statement stmt = conn.createStatement();
      ResultSet rs = stmt.executeQuery("SELECT '" + reversedConcat + "' AS reversed_concatenation");
      while (rs.next()) {
        String reversedConcatResult = rs.getString("reversed_concatenation");
        System.out.println("Reversed concatenation of sentence and mixedCase strings: " + reversedConcatResult);
      }
      conn.close();
    } catch (SQLException e) {
      System.out.println("Error creating string objects: " + e.getMessage());
    }
  }
}
