const puzzlePieces = document.querySelectorAll('.puzzle-piece');
let emptyPiece;
// Shuffle the puzzle pieces
function shufflePieces() {
  const piecesArray = Array.from(puzzlePieces);
  const shuffledArray = piecesArray.sort(() => Math.random() - 0.5);
  shuffledArray.forEach((piece, index) => {
    piece.style.order = index;
    if (piece.classList.contains('empty')) {
      emptyPiece = piece;
    }
  });
}
// Move the puzzle piece
function movePiece(piece) {
  const currentOrder = piece.style.order;
  const emptyOrder = emptyPiece.style.order;
  const diff = Math.abs(currentOrder - emptyOrder);
  if ((diff === 1 && Math.floor(currentOrder / 3) === Math.floor(emptyOrder / 3)) || diff === 3) {
    piece.style.order = emptyOrder;
    emptyPiece.style.order = currentOrder;
    emptyPiece = piece;
  }
}
