import csv
import random
def generate_phrase():
    # Generate a random phrase
    adjectives = ['serene', 'calm', 'peaceful', 'tranquil', 'quiet']
    nouns = ['lakeside', 'lake view', 'waterfront', 'shoreline', 'water edge']
    return random.choice(adjectives) + ' ' + random.choice(nouns)
def encrypt_phrase(phrase):
    # Encrypt the phrase using Caesar Cipher with key 13
    encrypted = ''
    for char in phrase:
        if char.isalpha():
            if char.isupper():
                encrypted += chr((ord(char) - 65 + 13) % 26 + 65)
            else:
                encrypted += chr((ord(char) - 97 + 13) % 26 + 97)
        else:
            encrypted += char
    return encrypted
def save_to_csv(phrase, author, date):
    # Save the encrypted phrase, author, and date to a CSV file
    with open('phrases.csv', 'a', newline='') as csvfile:
        writer = csv.writer(csvfile)
        writer.writerow([encrypt_phrase(phrase), author, date])
def read_from_csv():
    # Read the encrypted phrase, author, and date from the CSV file
    with open('phrases.csv', newline='') as csvfile:
        reader = csv.reader(csvfile)
        for row in reader:
            phrase = ''
            for char in row[0]:
                if char.isalpha():
                    if char.isupper():
                        phrase += chr((ord(char) - 65 - 13) % 26 + 65)
                    else:
                        phrase += chr((ord(char) - 97 - 13) % 26 + 97)
                else:
                    phrase += char
            print(f'Author: {row[1]}')
            print(f'Date: {row[2]}')
            print(f'Phrase: {phrase}\n')
# Generate a new phrase
