#include <iostream>
#include <string>
#include <random>
struct Node {
    int value;
    std::string str;
    Node* prev;
    Node* next;
};
Node* createNode(int value, const std::string& str) {
    Node* node = new Node;
    node->value = value;
    node->str = str;
    node->prev = nullptr;
    node->next = nullptr;
    return node;
}
void insertNode(Node*& head, Node* node) {
    if (head == nullptr) {
        head = node;
    } else {
        Node* curr = head;
        while (curr->next != nullptr && curr->next->value < node->value) {
            curr = curr->next;
        }
        if (curr->value <= node->value) {
            node->prev = curr;
            node->next = curr->next;
            if (curr->next != nullptr) {
                curr->next->prev = node;
            }
            curr->next = node;
        } else {
            node->prev = curr->prev;
            node->next = curr;
            if (curr->prev != nullptr) {
                curr->prev->next = node;
            } else {
                head = node;
            }
            curr->prev = node;
        }
    }
}
void printListForward(const Node* head) {
    while (head != nullptr) {
        std::cout << head->value << " " << head->str << std::endl;
        head = head->next;
    }
}
void printListBackward(const Node* tail) {
    while (tail != nullptr) {
        std::cout << tail->value << " " << tail->str << std::endl;
        tail = tail->prev;
    }
}
void removeEvenNodes(Node*& head) {
    Node* curr = head;
    while (curr != nullptr) {
        if (curr->value % 2 == 0) {
            if (curr->prev != nullptr) {
                curr->prev->next = curr->next;
            } else {
                head = curr->next;
            }
            if (curr->next != nullptr) {
                curr->next->prev = curr->prev;
            }
            Node* temp = curr;
            curr = curr->next;
            delete temp;
        } else {
            curr = curr->next;
        }
    }
}
int main() {
    const int min = 1;
    const int max = 100;
    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<int> dis(min, max);
    Node* head = nullptr;
    while (true) {
        std::cout << "Enter a string (up to 20 characters) or 'quit' to stop: ";
        std::string str;
        std::getline(std::cin, str);
        if (str == "quit") {
            break;
        }
        if (str.length() > 20) {
            std::cerr << "Error: string too long." << std::endl;
            continue;
        }
        int value = dis(gen);
        Node* node = createNode(value, str);
        insertNode(head, node);
    }
    std::cout << "List in ascending order:" << std::endl;
    printListForward(head);
    removeEvenNodes(head);
    std::cout << "List after removing even nodes:" << std::endl;
    printListForward(head);
    std::cout << "List in descending order:" << std::endl;
    Node* tail = head;
    while (tail != nullptr && tail->next != nullptr) {
        tail = tail->next;
    }
    printListBackward(tail);
    // Free memory
    while (head != nullptr) {
        Node* temp = head;
        head = head->next;
        delete temp;
    }
    return 0;
}
